-- PostgreSQL Demo Data Backup Script for Trading Simulation
-- Executable on a fresh database initialized with schema.sql
-- ============================================================

BEGIN;

-- Clean default seed data to avoid duplicate key conflicts
TRUNCATE TABLE dividend_payments, dividends, ipo_applications, ipos, trades, price_history, watchlist, portfolio, orders, stop_loss_orders, users, stocks, sectors CASCADE;

-- Data for table: sectors
