-- ============================================================
-- Reset Primary Key Sequences
-- ============================================================
SELECT setval('sectors_sector_id_seq', COALESCE((SELECT MAX(sector_id) FROM sectors), 1));
SELECT setval('users_user_id_seq', COALESCE((SELECT MAX(user_id) FROM users), 1));
SELECT setval('orders_order_id_seq', COALESCE((SELECT MAX(order_id) FROM orders), 1));
SELECT setval('price_history_history_id_seq', COALESCE((SELECT MAX(history_id) FROM price_history), 1));
SELECT setval('trades_trade_id_seq', COALESCE((SELECT MAX(trade_id) FROM trades), 1));
SELECT setval('ipos_ipo_id_seq', COALESCE((SELECT MAX(ipo_id) FROM ipos), 1));
SELECT setval('ipo_applications_app_id_seq', COALESCE((SELECT MAX(app_id) FROM ipo_applications), 1));
SELECT setval('dividends_dividend_id_seq', COALESCE((SELECT MAX(dividend_id) FROM dividends), 1));
SELECT setval('dividend_payments_payment_id_seq', COALESCE((SELECT MAX(payment_id) FROM dividend_payments), 1));
SELECT setval('stop_loss_orders_sl_id_seq', COALESCE((SELECT MAX(sl_id) FROM stop_loss_orders), 1));

COMMIT;
